def merge_intervals(intervals):
    normalized = []
    for a, b in intervals:
        if a <= b:
            normalized.append([a, b])
        else:
            normalized.append([b, a])
    if not normalized:
        return []
    normalized.sort(key=lambda x: x[0])
    merged = [normalized[0][:]]
    for cur in normalized[1:]:
        prev = merged[-1]
        if cur[0] <= prev[1]:
            if cur[1] > prev[1]:
                prev[1] = cur[1]
        else:
            merged.append(cur[:])
    return merged
